(233621, 'ruRU', 'Получите 20-й уровень известности у сил Зул\'джарры', 69497),
(224234, 'ruRU', 'Войска противника', 69497),
(232506, 'ruRU', 'Победите плодящихся ядорожденных', 69497),
(231319, 'ruRU', 'Светильник хмелеварни Буйных Портеров', 69497),
(231315, 'ruRU', 'Чэнь и Флинн', 69497),
