INSERT INTO `currency_types_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3356, 'ruRU', 'Неиспорченные кристаллы маны', 'Можно получить после достижения 9-го уровня на пути участника вылазки. Добывается из богатых сундуков с помощью отреставрированных ключей в многообещающих вылазках 11-го уровня. Также можно обменять у Зах\'рана на могущественное снаряжение.', 69497),
(3418, 'ruRU', 'Туманный сердечник Бездны', 'Можно трансмутировать в мощное снаряжение после победы над сильными врагами в рейдах Midnight или прохождения эпохальных подземелий с ключом, многообещающих вылазок и охоты в кошмарном режиме.\n\nПредметы можно собирать один раз на каждом уровне сложности, пока вы не трансмутируете все предметы для текущей специализации.', 69497),
(3509, 'ruRU', 'Пыль искры прилива', 'Магический осадок, который образуется вместе с искрами прилива. Помогает отслеживать, сколько искр прилива вы уже получили в 2-м сезоне Midnight.\n\nЕсли по ходу сезона вам не хватает искр, исследуйте контент максимального уровня: вылазки, подземелья в режиме \"Эпохальный+\", рейды, арены, поля боя и некоторые события в открытом мире.', 69497);
