INSERT INTO `journal_encounter_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2879, 'ruRU', 'Извивающийся виток', 'В безумной борьбе за пропитание, где потомки Ула\'тек пожирали друг друга, уцелело лишь одно создание. С каждой новой победой это отвратительное чудовище, известное как Извивающийся виток, становится только сильнее.', 69497);
