INSERT INTO `scenario_step_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `VerifiedBuild`) VALUES
(17053, 'ruRU', 'Войдите в проклятые залы под Печатью гнева и уничтожьте таящиеся там угрозы.', 'Зачистка Проклятых глубин', 69497),
(17052, 'ruRU', 'Найдите способ проникнуть в Проклятые глубины.', 'Проникновение в Проклятые глубины', 69497),
(17048, 'ruRU', 'Приготовьтесь к нападению на Клоаку.', 'Подготовка к атаке', 69497),
(17044, 'ruRU', 'Войдите в Клоаку и победите там врагов.', 'Очищение Клоаки', 69497),
(17032, 'ruRU', 'Готовьтесь, надвигается волна змей.', 'Пресмыкающиеся из глубин', 69497),
(17030, 'ruRU', 'Мастера огня готовят призрачные погребальные костры.', 'Возжигание костров', 69497),
(17028, 'ruRU', 'Обнаружен странный тайник!', 'Осмотр тайника', 69497),
(16919, 'ruRU', 'Пройдите через порталы и уничтожьте кладку Руук\'джар.', 'Уничтожение кладки', 69497),
(16918, 'ruRU', 'Дождитесь открытия портала.', 'Открытие портала', 69497),
(16876, 'ruRU', 'Тайник открыт.', 'Открытие тайника', 69497),
(16875, 'ruRU', 'Отнесите в тайник три посоха от каждого камня.', 'Возвращение посохов', 69497),
(16873, 'ruRU', 'Соберите зловещих духов и сожгите их на призрачных погребальных кострах. Донесите пламя костров до оскверненных саркофагов и подожгите их.', 'Избавление от нежити', 69497),
(16858, 'ruRU', 'Используйте святилища для сбора нечистых сфер.', 'Помощь святилищ неба и земли', 69497),
(16856, 'ruRU', 'Убейте змей и прервите ритуалы, чтобы уберечь храм.', 'Оборона от змей', 69497),
(16853, 'ruRU', 'Святилища насыщаются силой.', 'Усиление святилищ', 69497),
(17336, 'ruRU', 'Проложите путь через полчища врагов к сердцу Отравленной бездны и не дайте Ула\'тек вырваться из заточения.', 'Гробница Ула\'тек', 69497),
(17329, 'ruRU', 'Проложите путь через полчища врагов к сердцу Отравленной бездны и сойдитесь в схватке с Ула\'тек.', 'Гробница Ула\'тек', 69497),
(17328, 'ruRU', 'Змеиные чудовища захватили древние залы, где упокоились жертвы душителей душ.', 'Змеиное логово', 69497),
(17327, 'ruRU', 'Вашник Тлетворный занимается ядами Ула\'тек в Зале заражения, перегоняя их в еще более смертельные образцы.', 'Эссенция яда', 69497);
